import {weeks,lessons} from './data/curriculum.js';
import {categories,concepts,questions} from './data/concepts.js';
import {exercises} from './data/exercises.js';
import {labDefinitions,renderLab,bindLab} from './labs.js';
import {STORAGE_KEY,createState,normalizeState,quizStats,currentWeek,escapeHTML as e,localDate} from './state.js';

const catalog={weeks,lessons,categories,concepts,questions,exercises};
let state;try{const raw=localStorage.getItem(STORAGE_KEY);state=raw?normalizeState(JSON.parse(raw),catalog):createState();}catch{state=createState();}
let conceptSearch='',conceptCategory='all',bookmarksOnly=false,quiz=null,quizMode='diagnostic',selectedAnswer=null;
let cleanupLab=null,runner=null,runnerTimeout=null,runnerBusy=false,runResults={},hintCounts={},menuOpen=false;
const root=document.getElementById('app');
const paths={
 home:'M3 10l9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z',
 book:'M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-2H3V4z M13 7a3 3 0 0 1 3-3h5v15h-4a4 4 0 0 0-4 2',
 map:'M12 3v6M6 15l4-5M18 15l-4-5 M9 6a3 3 0 1 0 6 0a3 3 0 1 0-6 0 M2 18a3 3 0 1 0 6 0a3 3 0 1 0-6 0 M16 18a3 3 0 1 0 6 0a3 3 0 1 0-6 0',
 flask:'M9 3h6M10 3v7L4 20a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1l-6-10V3M7 15h10',
 code:'M8 7l-5 5 5 5M16 7l5 5-5 5M14 4l-4 16',
 exam:'M8 4H5v17h14V4h-3M8 3h8v4H8zM8 12l2 2 5-5M8 18h7',
 note:'M5 3h14v18H5zM8 7h8M8 11h8M8 15h5',
 settings:'M12 8a4 4 0 1 0 0 8a4 4 0 0 0 0-8M4 9l-2 1v4l2 1 1 2v2l4 2 2-1h2l2 1 4-2v-2l1-2 2-1v-4l-2-1-1-2V5l-4-2-2 1h-2L9 3 5 5v2z',
 arrow:'M5 12h14M14 7l5 5-5 5',chevron:'M9 5l7 7-7 7',search:'M10 3a7 7 0 1 0 0 14a7 7 0 0 0 0-14M15 15l6 6',
 check:'M5 12l4 4L19 6',close:'M6 6l12 12M18 6L6 18',clock:'M12 3a9 9 0 1 0 0 18a9 9 0 0 0 0-18M12 7v5l3 2',
 layers:'M12 3L2 8l10 5 10-5-10-5M3 12l9 5 9-5M3 16l9 5 9-5',spark:'M12 2l3 7 7 3-7 3-3 7-3-7-7-3 7-3z',
 bookmark:'M6 3h12v18l-6-4-6 4z',download:'M12 3v12M7 10l5 5 5-5M4 16v5h16v-5',upload:'M12 16V4M7 9l5-5 5 5M4 16v5h16v-5',
 play:'M8 4l12 8-12 8z',plus:'M12 5v14M5 12h14',menu:'M4 6h16M4 12h16M4 18h16',back:'M19 12H5M10 7l-5 5 5 5',link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6zM8 12l3 3 5-6'
};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.layers}"/></svg>`;
const navs=[['dashboard','home','学习工作台'],['course','book','12 周学习路线'],['concepts','map','概念地图'],['labs','flask','交互实验室'],['code','code','代码练习'],['assessment','exam','测验与复习'],['notebook','note','实验手记']];
const route=()=>{const parts=location.hash.replace(/^#\/?/,'').split('/');return {page:parts[0]||'dashboard',id:decodeURIComponent(parts.slice(1).join('/')||'')};};
const href=(page,id='')=>`#/${page}${id?'/'+encodeURIComponent(id):''}`;
const pct=()=>Math.round(state.completedLessons.length/lessons.length*100);
const safeURL=url=>{try{const u=new URL(url);return u.protocol==='https:'||u.protocol==='http:'?u.href:'#';}catch{return '#';}};
const sourcesHTML=sources=>(sources||[]).map(s=>`<a class="source-link" href="${e(safeURL(s.url))}" target="_blank" rel="noopener noreferrer">${e(s.label)} ↗</a>`).join('');
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3500);}
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch{toast('浏览器存储不可用或已满，请导出学习备份。');}}
function download(filename,contents,type='application/json'){const url=URL.createObjectURL(new Blob([contents],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function getNextLesson(){return lessons.find(l=>!state.completedLessons.includes(l.id))||lessons[0];}
function pageHeading(title,description,actions=''){return `<div class="page-heading"><div><h1>${e(title)}</h1><p>${e(description)}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;}
function shell(page,content){
 const active=page==='lesson'?'course':page,nav=navs.find(n=>n[0]===active),title=nav?.[2]||(page==='settings'?'学习设置':'学习工作台');
 return `<div class="layout">${menuOpen?'<div class="sidebar-backdrop" data-action="menu"></div>':''}<aside class="sidebar ${menuOpen?'open':''}" aria-label="主要导航"><a class="brand" href="#/dashboard"><span class="brand-mark">m<span>c</span></span><div><div class="brand-name">Model Craft</div><div class="brand-subtitle">大模型学习实验室</div></div></a><div class="nav-label">YOUR LEARNING SPACE</div><nav class="nav">${navs.map(([id,ic,label])=>`<a class="nav-link ${active===id?'active':''}" href="${href(id)}" ${active===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span></a>`).join('')}</nav><div class="sidebar-bottom"><div class="journey-mini"><div class="between"><span class="small">12 周 · 算法工程师之路</span><span class="small muted">${pct()}%</span></div><div class="progress-track" role="progressbar" aria-label="课程阅读进度" aria-valuenow="${pct()}" aria-valuemin="0" aria-valuemax="100"><div class="progress-fill" style="width:${pct()}%"></div></div><p class="small muted" style="margin-top:8px">${state.completedLessons.length} / ${lessons.length} 节已完成阅读</p></div><a class="nav-link ${active==='settings'?'active':''}" href="#/settings">${icon('settings')}<span>进度备份与设置</span></a><div class="user-row"><div class="avatar">S</div><div><p>Shawn 的学习空间</p><small class="muted">具身智能 / 世界模型</small></div></div></div></aside><div class="main-wrap"><header class="topbar"><div class="topbar-left"><button class="mobile-menu" data-action="menu" aria-label="打开导航" aria-expanded="${menuOpen}">${icon('menu')}</button><div class="breadcrumb"><span>我的学习空间</span><span>/</span><strong>${title}</strong></div></div><div class="topbar-right"><button class="top-search" data-action="search">${icon('search')}<span>搜索一个概念…</span><kbd>⌘ K</kbd></button><span class="local-tag"><i class="status-dot"></i>进度保存在本机</span><a href="#/settings" class="avatar" aria-label="学习设置">S</a></div></header><main class="content" id="main" tabindex="-1">${content}<footer class="footer-note"><span class="row">${icon('shield')}记录真实理解，让每次实验都有依据。</span><span>MODEL CRAFT · LEARN BY BUILDING</span></footer></main></div></div>`;
}

function dashboard(){
 const next=getNextLesson(),week=weeks.find(w=>w.id===next.week)||weeks[0],stats=quizStats(state),passed=Object.values(state.codeResults).filter(r=>r.passed===r.total&&r.total>0).length;
 const phaseGroups=[{title:'让模型真正学会',sub:'训练基础 · 模型结构 · 诊断与评测',range:[1,2,3,4]},{title:'从语言走向世界',sub:'后训练 · 视觉表示 · 生成与世界模型',range:[5,6,7,8]},{title:'走进算法实践',sub:'KDA 记忆 · 具身策略 · 专项实验',range:[9,10,11,12]}];
 return pageHeading('今天，向模型内部走一步。','从理解一次参数更新，到独立完成世界模型实验。',`<span class="date-tag">${new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'long'}).format(new Date())}</span>`)+
 `<section class="hero"><div class="hero-copy"><div class="hero-top"><span class="badge badge-dark">WEEK ${String(next.week).padStart(2,'0')}</span><span>你的下一节课</span></div><h2>${e(next.title)}</h2><p>${e(next.summary)}</p><div class="hero-actions"><a class="btn btn-light" href="${href('lesson',next.id)}">${icon('play')} 开始学习 ${icon('arrow')}</a><small>${next.minutes} 分钟 · 理解 + 动手</small></div></div><div class="hero-art" aria-hidden="true"><div class="model-diagram"><svg class="connections" viewBox="0 0 340 195"><g fill="none" stroke="#83a995" stroke-width="1" opacity=".45"><path d="M50 40C80 40 70 65 103 65M50 79H103M50 118C80 118 75 100 103 100M228 64C265 64 265 65 292 65M228 90C260 90 265 105 292 105M228 115C270 115 260 145 292 145"/></g></svg><div class="node-column left"><div class="node-block">x₁</div><div class="node-block">x₂</div><div class="node-block">x₃</div></div><div class="model-core">${icon('layers')}<span>learn · predict</span><small style="color:#91ae98;font-size:9px">θ ← θ − η∇L</small></div><div class="node-column right"><div class="node-block">ŷ₁</div><div class="node-block">ŷ₂</div><div class="node-block">ŷ₃</div></div><div class="diagram-caption">DATA → MODEL → UNDERSTANDING</div></div></div></section>
 <div class="stats-row"><div class="panel stat"><div><div class="stat-label">课程阅读</div><div class="stat-value">${state.completedLessons.length}<small>/ ${lessons.length} 节</small></div></div><div class="stat-icon">${icon('book')}</div></div><div class="panel stat"><div><div class="stat-label">测验最近答对</div><div class="stat-value">${stats.correct}<small>/ ${stats.attempted||questions.length} ${stats.attempted?'道已答题':'道待挑战'}</small></div></div><div class="stat-icon orange">${icon('exam')}</div></div><div class="panel stat"><div><div class="stat-label">代码检查通过</div><div class="stat-value">${passed}<small>/ ${exercises.length} 个练习</small></div></div><div class="stat-icon blue">${icon('code')}</div></div></div>
 <div class="dashboard-grid"><section class="panel panel-pad"><div class="section-heading"><h2>你的 12 周成长路径</h2><a class="text-link" href="#/course">查看课程 ${icon('arrow')}</a></div>${phaseGroups.map((p,i)=>`<div class="phase-block"><div class="row"><div class="phase-number">0${i+1}</div><div><div class="phase-title">${p.title}</div><div class="phase-subtitle">${p.sub}</div></div></div><div class="week-pills">${p.range.map(n=>{const wl=lessons.filter(l=>l.week===n),done=wl.every(l=>state.completedLessons.includes(l.id));return `<a class="week-pill ${n===next.week?'current':''} ${done?'done':''}" href="#/course/${n}">第 ${n} 周${done?' ✓':''}</a>`}).join('')}</div></div>`).join('')}</section>
 <div class="stack"><section class="panel panel-pad"><div class="section-heading"><h2>本周学习清单</h2><span class="badge">第 ${next.week} 周</span></div>${lessons.filter(l=>l.week===next.week).map(l=>`<a class="task-item" href="${href('lesson',l.id)}"><span class="task-check ${state.completedLessons.includes(l.id)?'done':''}">${state.completedLessons.includes(l.id)?'✓':''}</span><div><h3>${e(l.title)}</h3><p>${l.minutes} 分钟 · ${state.completedLessons.includes(l.id)?'已完成阅读':'等待开始'}</p></div>${icon('chevron')}</a>`).join('')}<div class="next-note">本周产出：${e(week.deliverable)}</div></section><section class="panel panel-pad"><div class="section-heading"><h2>把模糊概念弄清楚</h2>${icon('map')}</div><p class="small muted">从你提到的术语出发，找到它们在模型中的位置。</p><div class="topic-row">${['SFT','LoRA','JEPA','KDA','世界模型','Diffusion'].map(t=>{const c=findConcept(t);return c?`<a class="chip" href="${href('concepts',c.id)}">${e(t)}</a>`:''}).join('')}</div><a class="text-link" style="margin-top:17px" href="#/concepts">探索 ${concepts.length} 个概念 ${icon('arrow')}</a></section></div></div>`;
}

function coursePage(id){
 const week=weeks.find(w=>w.id===Number(id))||weeks.find(w=>w.id===getNextLesson().week)||weeks[0];
 return pageHeading('每一周，都有可以验证的进步。','12 周 · 约 130 小时 · 先理解，再实现，最后独立设计实验。')+
 `<div class="course-layout"><aside class="week-list" aria-label="按周选择">${weeks.map(w=>{const done=lessons.filter(l=>l.week===w.id&&state.completedLessons.includes(l.id)).length;return `<a class="week-item ${w.id===week.id?'active':''}" href="#/course/${w.id}"><span class="week-index">${String(w.id).padStart(2,'0')}</span><div><strong>${e(w.title)}</strong><small>${done}/3 已读 · ${w.hours} 小时周预算</small></div></a>`}).join('')}</aside><div class="stack"><section class="panel week-intro"><span class="eyebrow">WEEK ${String(week.id).padStart(2,'0')} / 12</span><h2>${e(week.title)}</h2><p>${e(week.goal)}</p><div class="week-meta"><span>${e(week.phase)}</span><span>${week.hours} 小时 · 含实验与复盘</span><span>3 节主课</span></div></section>${lessons.filter(l=>l.week===week.id).map((l,i)=>`<a class="panel lesson-card" href="${href('lesson',l.id)}"><div class="lesson-number">${state.completedLessons.includes(l.id)?'✓':String(i+1).padStart(2,'0')}</div><div class="lesson-content"><h3>${e(l.title)}</h3><p>${e(l.summary)}</p><div class="lesson-meta"><span>${l.minutes} 分钟主课</span><span>正文 · 代码 · 理解检查</span>${state.completedLessons.includes(l.id)?'<span class="badge">已读</span>':''}</div></div>${icon('arrow')}</a>`).join('')}<section class="week-deliverable"><h3>这一周，你需要交付</h3><p>${e(week.deliverable)}</p><div class="row wrap space-top"><button class="btn btn-small btn-primary" data-action="week-quiz" data-week="${week.id}">检验本周理解 ${icon('arrow')}</button><a class="btn btn-small" href="#/notebook">写实验手记</a></div></section><p class="small muted">课程阅读只占一部分时间；周预算还包含代码实现、实验、查阅资料与复盘。未通过检查时，先回到对应概念。</p></div></div>`;
}

function lessonPage(id){
 const l=lessons.find(x=>x.id===id);if(!l)return notFound();const done=state.completedLessons.includes(id),next=lessons[lessons.indexOf(l)+1];
 return `<a class="text-link" style="margin-bottom:20px" href="#/course/${l.week}">${icon('back')} 第 ${l.week} 周课程</a><div class="lesson-layout"><article class="panel reading"><span class="eyebrow">WEEK ${String(l.week).padStart(2,'0')} · ${l.minutes} MIN</span><h1>${e(l.title)}</h1><p class="lead">${e(l.summary)}</p><div class="reading-section"><h2>学完这一课，你能</h2><ul>${l.objectives.map(o=>`<li>${e(o)}</li>`).join('')}</ul></div>${l.sections.map(s=>`<section class="reading-section"><h2>${e(s.title)}</h2>${(Array.isArray(s.body)?s.body:[s.body]).map(p=>`<p>${e(p)}</p>`).join('')}</section>`).join('')}<section class="reading-section"><h2>${e(l.example.title)}</h2><pre><code>${e(l.example.code)}</code></pre><p>${e(l.example.explanation)}</p></section><section class="reading-section"><h2>先合上正文，检查理解</h2><ol>${l.checkpoints.map(q=>`<li>${e(q)}</li>`).join('')}</ol><div class="callout">用自己的话回答，再用代码或例子验证。读完正文不等于通过掌握检查。</div></section><section class="reading-section"><h2>${e(l.practice.title)}</h2><ol>${l.practice.steps.map(s=>`<li>${e(s)}</li>`).join('')}</ol></section><section class="reading-section"><h2>继续查证</h2>${sourcesHTML(l.sources)}</section><div class="divider"></div><div class="between wrap"><button class="btn ${done?'':'btn-primary'}" data-action="complete-lesson" data-id="${e(id)}">${icon(done?'check':'book')}${done?'已完成阅读 · 点击撤销':'标记已完成阅读'}</button>${next?`<a class="text-link" href="${href('lesson',next.id)}">下一课 ${icon('arrow')}</a>`:''}</div></article><aside class="lesson-aside stack"><div class="panel"><h3>把理解变成证据</h3><ul><li>阅读：明确输入、输出和目标</li><li>实现：运行代码或完成实验</li><li>检验：用新场景回答问题</li></ul><button class="btn btn-primary" data-action="week-quiz" data-week="${l.week}">第 ${l.week} 周测验</button><a class="btn" href="#/code">进入代码练习</a><a class="btn btn-ghost" href="#/labs">打开交互实验室</a></div><div class="panel"><h3>这节课的理解笔记</h3><label for="lesson-note">我的解释 / 还不清楚的地方</label><textarea id="lesson-note" data-lesson="${e(id)}" placeholder="尝试用一个具体例子解释…">${e(state.notes[id]||'')}</textarea><p class="small muted" id="note-status" style="margin-top:8px">输入后自动保存在本机</p></div></aside></div>`;
}

function findConcept(term){const needle=term.toLowerCase();return concepts.find(c=>[c.id,c.term,c.english,...(c.aliases||[])].some(v=>String(v).toLowerCase()===needle))||concepts.find(c=>[c.term,c.english,...(c.aliases||[])].join(' ').toLowerCase().includes(needle));}
function conceptsPage(id){
 const filtered=concepts.filter(c=>(conceptCategory==='all'||c.category===conceptCategory)&&(!bookmarksOnly||state.bookmarks.includes(c.id))&&[c.term,c.english,c.definition,...(c.aliases||[])].join(' ').toLowerCase().includes(conceptSearch.toLowerCase()));
 const selected=concepts.find(c=>c.id===id)||filtered[0];
 return pageHeading('给每个概念，找到正确的位置。',`${concepts.length} 个概念 · 多个互补维度 · 每个概念都有例子、误区与来源。`)+`<div class="search-box">${icon('search')}<input type="search" class="field" id="concept-search" value="${e(conceptSearch)}" placeholder="搜索预训练、AR、LoRA、JEPA、视觉塔、KDA、MMLU…" aria-label="搜索概念"></div><div class="filter-bar"><button class="filter-button ${conceptCategory==='all'?'active':''}" data-action="category" data-id="all">全部概念</button>${categories.map(c=>`<button class="filter-button ${conceptCategory===c.id?'active':''}" data-action="category" data-id="${e(c.id)}">${e(c.label)}</button>`).join('')}<button class="filter-button ${bookmarksOnly?'active':''}" data-action="bookmarks">已收藏</button><span class="result-count">${filtered.length} 个结果</span></div><div class="concept-layout"><div class="concept-list" aria-label="概念列表">${filtered.length?filtered.map(c=>`<a class="concept-item ${selected?.id===c.id?'active':''}" href="${href('concepts',c.id)}"><div><strong>${e(c.term)}</strong><small>${e(c.english)}</small></div>${c.status?`<span class="badge badge-orange">${e(c.status)}</span>`:`<span class="badge badge-gray">W${c.week}</span>`}</a>`).join(''):'<div class="empty"><h3>没有找到这个概念</h3><p>试试英文缩写，或清除当前分类筛选。</p><button class="btn btn-small" data-action="clear-search">清除筛选</button></div>'}</div><article class="panel concept-detail">${selected&&filtered.length?conceptDetail(selected):'<div class="empty">从左侧选择一个概念开始。</div>'}</article></div>`;
}
function conceptDetail(c){const related=(c.related||[]).map(id=>concepts.find(x=>x.id===id)).filter(Boolean),qs=questions.filter(q=>q.conceptId===c.id),correct=qs.filter(q=>state.answers[q.id]?.correct).length;
 return `<div class="between"><div class="row gap-sm wrap"><span class="badge">${e(categories.find(k=>k.id===c.category)?.label||c.category)}</span><span class="badge badge-gray">${e(c.level)} · 第 ${c.week} 周</span>${c.status?`<span class="badge badge-orange">${e(c.status)}</span>`:''}</div><button class="bookmark ${state.bookmarks.includes(c.id)?'active':''}" data-action="bookmark" data-id="${e(c.id)}" aria-label="${state.bookmarks.includes(c.id)?'取消收藏':'收藏'}${e(c.term)}" aria-pressed="${state.bookmarks.includes(c.id)}">${icon('bookmark')}</button></div><h2>${e(c.term)}</h2><div class="english">${e(c.english)}</div><p class="definition">${e(c.definition)}</p>${[['先建立直觉',c.analogy],['它怎样工作',c.mechanism],['放进一个具体例子',c.example],['最容易混淆的地方',c.pitfall]].map(([title,body])=>`<section class="concept-section"><h3>${title}</h3><p>${e(body)}</p></section>`).join('')}<section class="concept-section"><h3>与这些概念一起理解</h3><div class="topic-row">${related.map(r=>`<a class="chip" href="${href('concepts',r.id)}">${e(r.term)}</a>`).join('')}</div></section><section class="concept-section"><h3>原始资料与查证入口</h3><div class="concept-source">${sourcesHTML(c.sources)||'<span class="small muted">需要结合你所在团队的具体全称或实现确认。</span>'}</div></section><div class="between wrap space-top"><a class="btn btn-small" href="#/course/${c.week}">学习对应课程 ${icon('arrow')}</a>${qs.length?`<button class="btn btn-small btn-primary" data-action="concept-quiz" data-id="${e(c.id)}">理解检查 · ${correct}/${qs.length}</button>`:'<span class="small muted">结合课程练习验证理解</span>'}</div>`;}

function labsPage(id){return pageHeading('动一下参数，看见机制。','先预测会发生什么，再操作，再把观察写成可验证的解释。')+renderLab(id);}
function codePage(id){const ex=exercises.find(x=>x.id===id)||exercises[0],result=state.codeResults[ex.id];return pageHeading('亲手实现，才算真正理解。','Python 练习在浏览器内真实执行；PyTorch 训练项目可下载到 Mac 或 H20 运行。')+`<div class="coding-layout"><aside class="exercise-list">${exercises.map(x=>`<a class="exercise-item ${x.id===ex.id?'active':''}" href="${href('code',x.id)}"><strong>${state.codeResults[x.id]?.passed===state.codeResults[x.id]?.total&&state.codeResults[x.id]?.total?'✓ ':''}${e(x.title)}</strong><small>第 ${x.week} 周 · ${x.minutes} 分钟</small></a>`).join('')}<a class="exercise-item" href="./downloads/model-craft-labs.zip" download><strong>↓ 下载本地训练包</strong><small>微型语言模型 + 世界模型</small></a></aside><div class="stack"><section class="panel exercise-intro"><div class="row wrap gap-sm"><span class="badge">WEEK ${ex.week}</span><span class="badge badge-blue">真实 Python · 标准库</span>${result?`<span class="badge ${result.passed===result.total?'':'badge-orange'}">上次通过 ${result.passed}/${result.total}</span>`:''}</div><h2>${e(ex.title)}</h2><p>${e(ex.summary)}</p><ol>${ex.instructions.map(s=>`<li>${e(s)}</li>`).join('')}</ol></section><section class="editor-wrap"><div class="editor-toolbar"><span class="mono">${e(ex.id)}.py</span><div class="row gap-sm"><button class="btn btn-small btn-ghost" data-action="code-hint" data-id="${e(ex.id)}">逐步提示</button><button class="btn btn-small btn-ghost" data-action="code-solution" data-id="${e(ex.id)}">参考解法</button><button class="btn btn-small btn-ghost" data-action="code-reset" data-id="${e(ex.id)}">重置</button></div></div><textarea class="code-editor" id="code-editor" data-exercise="${e(ex.id)}" aria-label="Python 代码编辑器" spellcheck="false" autocapitalize="off" autocomplete="off">${e(state.code[ex.id]??ex.starter)}</textarea><div class="editor-footer"><span class="small muted">代码自动保存 · 首次运行需联网加载 Python</span><div class="row gap-sm"><button class="btn btn-small" data-action="download-code" data-id="${e(ex.id)}" aria-label="下载当前 Python 代码">${icon('download')}</button><button class="btn btn-primary" id="run-code" data-action="run-code" data-id="${e(ex.id)}">${icon('play')} 运行并检查</button><button class="btn hidden" id="stop-code" data-action="stop-code">停止</button></div></div></section><div id="code-hints">${renderHints(ex)}</div><section class="panel code-result" id="code-result" aria-live="polite">${renderCodeResult(ex.id)}</section><div class="download-grid"><a class="panel download-card" href="./downloads/tiny_lm.py" download>${icon('download')}<h3>微型语言模型训练</h3><p>PyTorch · 因果预测 · 训练与验证 · checkpoint</p></a><a class="panel download-card" href="./downloads/tiny_world_model.py" download>${icon('download')}<h3>动作条件世界模型</h3><p>合成轨迹 · 动态预测 · 多步 rollout · 简单基线</p></a></div><p class="small muted">浏览器练习使用独立 Python 运行时，不支持 PyTorch。训练包提供本地执行说明；训练时间和规模由你的设备与配置决定。</p></div></div>`;}
function renderHints(ex){return (hintCounts[ex.id]||0)?`<div class="hint">${ex.hints.slice(0,hintCounts[ex.id]).map((h,i)=>`<p>提示 ${i+1}：${e(h)}</p>`).join('')}</div>`:'';}
function renderCodeResult(id){const r=runResults[id];if(!r)return `<h3>运行结果</h3><p class="small muted">完成函数后点击“运行并检查”。检查器会执行真实断言，并展示每项结果。</p>`;if(r.loading)return `<h3>正在执行</h3><p class="small muted">${e(r.message)}</p>`;return `<h3>${r.error?'执行出现错误':`检查通过 ${r.tests.filter(t=>t.passed).length} / ${r.tests.length}`}</h3>${r.error?`<pre>${e(r.error)}</pre>`:''}${(r.tests||[]).map(t=>`<div class="test-row ${t.passed?'':'fail'}">${icon(t.passed?'check':'close')}${e(t.name)}</div>${t.error?`<pre>${e(t.error)}</pre>`:''}`).join('')}${r.stdout?`<h3 style="margin-top:20px">标准输出</h3><pre>${e(r.stdout)}</pre>`:''}${!r.error&&r.tests.length&&r.tests.every(t=>t.passed)?'<div class="callout" style="margin-top:16px">检查通过。再尝试解释边界情况，并修改输入验证你理解了机制。</div>':''}`;}

function assessmentPage(){const stats=quizStats(state);return pageHeading('检验理解，找到下一步。','每一道题都围绕实际判断。回答之后查看解释，再回到对应概念。')+`<div class="quiz-layout"><section class="panel quiz-card" id="quiz-main">${quiz?renderQuiz():`<div class="quiz-summary"><span class="eyebrow">CHECK YOUR UNDERSTANDING</span><div class="score-ring" style="--score:${stats.attempted?Math.round(stats.correct/stats.attempted*100):0}"><strong>${stats.attempted?Math.round(stats.correct/stats.attempted*100)+'%':'—'}</strong></div><h2>从一轮诊断开始</h2><p>先完成 8 道跨主题问题，发现你已经理解的内容。<br>当前已回答 ${stats.attempted} 道，${stats.wrong} 道需要复习。</p><button class="btn btn-primary" data-action="start-quiz">开始诊断 ${icon('arrow')}</button><p class="welcome-note">答题记录反映最近一次表现；课程阅读与代码通过分别记录。</p></div>`}</section><aside class="panel quiz-settings"><div><label for="quiz-mode">选择检查范围</label><select id="quiz-mode"><option value="diagnostic" ${quizMode==='diagnostic'?'selected':''}>全景诊断 · 8 题</option><option value="review" ${quizMode==='review'?'selected':''}>错题复习</option>${weeks.map(w=>`<option value="week-${w.id}" ${quizMode==='week-'+w.id?'selected':''}>第 ${w.id} 周 · 理解检查</option>`).join('')}<option value="stage-4" ${quizMode==='stage-4'?'selected':''}>第一阶段 · 第 1–4 周</option><option value="stage-8" ${quizMode==='stage-8'?'selected':''}>第二阶段 · 第 1–8 周</option><option value="stage-12" ${quizMode==='stage-12'?'selected':''}>最终综合 · 12 周</option></select><button class="btn" data-action="start-quiz">开始新一轮</button><div class="divider"></div><h3>掌握检查</h3><p class="small muted" style="margin-top:10px">每轮建议达到 80%。阶段验收还需要代码和实验报告，选择题不能替代实践。</p></div><div><div class="divider"></div><h3>最近需要复习</h3>${questions.filter(q=>state.answers[q.id]&&!state.answers[q.id].correct).slice(-5).map(q=>`<a class="review-item" style="display:block" href="${href('concepts',q.conceptId)}">${e(concepts.find(c=>c.id===q.conceptId)?.term||q.question)} →</a>`).join('')||'<p class="small muted" style="margin-top:12px">尚无错题记录。完成测验后，这里会关联到对应概念。</p>'}</div></aside></div>`;}
function renderQuiz(){
 if(quiz.finished){const score=Math.round(quiz.correct/quiz.pool.length*100);return `<div class="quiz-summary"><span class="eyebrow">${e(quiz.label)}</span><div class="score-ring" style="--score:${score}"><strong>${score}%</strong></div><h2>${score>=80?'这轮理解检查通过':'找到值得再学一遍的地方'}</h2><p>答对 ${quiz.correct} / ${quiz.pool.length} 道。${score>=80?'接下来用代码与实验检验迁移能力。':'查看下方解释，回到相关课程后再做一次。'}</p><button class="btn btn-primary" data-action="start-quiz">再做一轮</button></div><div class="divider"></div>${quiz.responses.map((r,i)=>`<div class="review-item"><div class="row">${icon(r.correct?'check':'close')}<strong>${i+1}. ${e(r.question.question)}</strong></div><p style="margin-top:9px">${e(r.question.explanation)}</p><a class="text-link" href="${href('concepts',r.question.conceptId)}">回到概念 →</a></div>`).join('')}`;}
 const q=quiz.pool[quiz.index],response=quiz.responses[quiz.index];return `<div class="between"><span class="badge">${e(quiz.label)}</span><span class="small muted">${quiz.index+1} / ${quiz.pool.length}</span></div><div class="progress-track"><div class="progress-fill" style="width:${quiz.index/quiz.pool.length*100}%"></div></div><div class="quiz-kicker">第 ${q.week} 周 · 情境判断</div><h2 class="quiz-question">${e(q.question)}</h2><div class="quiz-options">${q.options.map((o,i)=>`<button class="quiz-option ${selectedAnswer===i?'selected':''} ${response&&i===q.answer?'correct':''} ${response&&i===response.selected&&!response.correct?'incorrect':''}" data-action="quiz-option" data-index="${i}" ${response?'disabled':''}><span class="option-letter">${String.fromCharCode(65+i)}</span><span>${e(o)}</span></button>`).join('')}</div>${response?`<div class="quiz-explanation ${response.correct?'':'wrong'}"><strong>${response.correct?'回答正确':'重新检查你的判断'}</strong><p>${e(q.explanation)}</p>${q.misconception?`<p class="small" style="margin-top:8px">常见误区：${e(q.misconception)}</p>`:''}<a class="text-link" style="margin-top:10px" href="${href('concepts',q.conceptId)}">查看相关概念 →</a></div>`:''}<div class="quiz-actions"><span class="small muted">${response?'先解释原因，再继续。':'请选择最合适的答案。'}</span>${response?`<button class="btn btn-primary" data-action="quiz-next">${quiz.index+1===quiz.pool.length?'查看结果':'下一题'} ${icon('arrow')}</button>`:`<button class="btn btn-primary" data-action="quiz-submit" ${selectedAnswer===null?'disabled':''}>提交判断</button>`}</div>`;
}

function notebookPage(){return pageHeading('让每一次实验，都留下证据。','记录假设、对照与结果。进度保存在当前浏览器，可随时导出备份。',`<button class="btn btn-primary" data-action="new-experiment">${icon('plus')} 新建实验</button>`)+`<div class="notebook-layout"><div class="stack">${state.experiments.length?state.experiments.map(x=>`<article class="panel experiment-card"><div class="between"><span class="badge ${x.status==='analyzed'?'':'badge-gray'}">${{draft:'计划中',running:'进行中',analyzed:'已分析'}[x.status]||'计划中'}</span><span class="small muted">${e((x.updatedAt||x.createdAt||'').slice(0,10))}</span></div><h3 style="margin-top:13px">${e(x.title)}</h3><p>${e(x.hypothesis)}</p>${x.result?`<div class="callout" style="margin-top:14px">${e(x.result)}</div>`:''}<div class="experiment-meta"><span>${x.variable?'变量：'+e(x.variable):'待明确实验变量'}</span>${x.seed?`<span>seed: ${e(x.seed)}</span>`:''}</div><div class="experiment-actions"><button class="btn btn-small" data-action="edit-experiment" data-id="${e(x.id)}">查看 / 编辑</button><button class="btn btn-small btn-ghost" data-action="export-experiment" data-id="${e(x.id)}">导出 Markdown</button><button class="btn btn-small btn-ghost btn-danger" data-action="delete-experiment" data-id="${e(x.id)}">删除</button></div></article>`).join(''):`<div class="panel empty">${icon('note')}<h3>你的第一个实验，从一个问题开始。</h3><p>“更大的学习率会更快收敛吗？”或“只改输入噪声，会怎样影响 rollout？”先写预测，再记录证据。</p><button class="btn btn-primary" data-action="new-experiment">创建第一份实验记录</button></div>`}</div><aside class="notebook-aside stack"><section class="panel panel-pad"><h3>一份可复现的实验记录</h3><div class="divider"></div>${['明确你想验证的假设','保留可以复现的基线','记录数据版本与划分','控制变量与训练预算','比较独立评测和失败样例','写下结论的适用范围'].map((s,i)=>`<p class="small muted" style="margin:10px 0">${i+1}. ${s}</p>`).join('')}</section><section class="panel panel-pad"><span class="badge badge-orange">专项实验候选</span><h3 style="margin-top:12px">视觉 AR 的输入噪声，会影响连续预测吗？</h3><p class="small muted" style="margin-top:10px">比较训练时的单步误差与自由运行误差。控制数据、模型和预算；结果不提升也要解释证据。</p><button class="btn btn-small" style="margin-top:16px" data-action="experiment-template">使用实验模板</button></section></aside></div>`;}

function settingsPage(){const terms=['预训练','后训练','PT','AR','SFT','LoRA','JEPA','视觉塔','KDA','Decoder-only','世界模型','具身','LSD','MMLU','MMMU','MMStar','rewardx'];return pageHeading('你的路线，你的学习记录。','阅读、测验、代码与实验分别记录。导出备份可以跨设备继续学习。')+`<div class="settings-grid"><section class="panel settings-section"><h2>学习计划</h2><p>主方向：具身智能 / 世界模型训练算法。12 周，约 130 小时。数学按实验需要补充。</p><label for="start-date">计划开始日期<input id="start-date" type="date" value="${e(state.startDate)}"></label><p class="small muted" style="margin-top:12px">按日历目前为第 ${currentWeek(state)} 周；课程全部可访问，建议按掌握情况推进。</p><div class="callout">三个月的目标是建立可验证的训练能力和项目证据。完成页面或测验不会自动等同于转岗成功。</div></section><section class="panel settings-section"><h2>进度备份</h2><p>记录保存在当前浏览器的本地存储中。清除浏览器数据或更换设备前，请先导出。此版本不提供跨设备自动同步。</p><div class="row wrap"><button class="btn btn-primary" data-action="export-progress">${icon('download')} 导出全部进度</button><button class="btn" data-action="import-progress">${icon('upload')} 导入备份</button></div><input class="hidden" type="file" id="import-file" accept="application/json,.json"><div class="divider"></div><p>导出包括阅读进度、答题、代码、笔记和实验记录；不包含公司仓库源码或训练权重。</p><button class="btn btn-small btn-danger" data-action="reset-progress">清空本机学习记录</button></section></div><section class="panel panel-pad space-top"><div class="section-heading"><h2>你提出的概念，都有对应入口</h2><span class="badge">覆盖检查</span></div><div class="coverage-grid">${terms.map(t=>{const c=findConcept(t);return c?`<a class="coverage-term" href="${href('concepts',c.id)}"><span>${e(t)}</span>${c.status?`<span class="badge badge-orange">${e(c.status)}</span>`:icon('check')}</a>`:`<div class="coverage-term">${e(t)} · 待补充</div>`}).join('')}</div><p class="small muted" style="margin-top:18px">PT、rewardx 需要团队语境确认；LSD 按 OmniFM 中的特定 codec 理解。条目存在表示已覆盖教学入口，不表示你已掌握。</p></section><section class="panel panel-pad space-top"><h2>本地训练材料</h2><p class="small muted" style="margin:12px 0">浏览器代码练习之外，使用独立 PyTorch 脚本练习真实的小模型训练。</p><div class="row wrap"><a class="btn" href="./downloads/model-craft-labs.zip" download>下载训练包 ${icon('download')}</a><a class="btn" href="./downloads/README.md" target="_blank">阅读运行说明 ↗</a></div></section>`;}
function notFound(){return '<section class="panel empty"><h3>没有找到这一页</h3><p>课程可能已经更新，请从学习路线继续。</p><a class="btn" href="#/course">返回课程</a></section>';}

function render({keepScroll=false}={}){
 cleanupLab?.();cleanupLab=null;const r=route();
 if(r.page!=='code'&&runnerBusy)stopRunner(false);
 const pages={dashboard,course:()=>coursePage(r.id),lesson:()=>lessonPage(r.id),concepts:()=>conceptsPage(r.id),labs:()=>labsPage(r.id),code:()=>codePage(r.id),assessment:assessmentPage,notebook:notebookPage,settings:settingsPage};
 const scroll=window.scrollY;root.innerHTML=shell(r.page,(pages[r.page]||notFound)());
 if(r.page==='labs')cleanupLab=bindLab(r.id,openExperiment);
 bindInputs();if(keepScroll)window.scrollTo(0,scroll);else window.scrollTo(0,0);
 document.title=`${navs.find(n=>n[0]===(r.page==='lesson'?'course':r.page))?.[2]||'学习空间'} · Model Craft`;
}
function bindInputs(){
 const search=document.getElementById('concept-search');search?.addEventListener('input',ev=>{const pos=ev.target.selectionStart;conceptSearch=ev.target.value;const r=route();root.querySelector('main').innerHTML=conceptsPage('')+`<footer class="footer-note"><span>概念地图 · MODEL CRAFT</span></footer>`;bindInputs();const input=document.getElementById('concept-search');input.focus();try{input.setSelectionRange(pos,pos);}catch{}});
 document.getElementById('lesson-note')?.addEventListener('input',ev=>{state.notes[ev.target.dataset.lesson]=ev.target.value;save();document.getElementById('note-status').textContent='已保存到本机';});
 const editor=document.getElementById('code-editor');editor?.addEventListener('input',ev=>{state.code[ev.target.dataset.exercise]=ev.target.value;save();});editor?.addEventListener('keydown',ev=>{if(ev.key==='Tab'){ev.preventDefault();const start=editor.selectionStart,end=editor.selectionEnd;editor.setRangeText('    ',start,end,'end');state.code[editor.dataset.exercise]=editor.value;save();}if((ev.metaKey||ev.ctrlKey)&&ev.key==='Enter'){ev.preventDefault();runCode(editor.dataset.exercise);}});
 document.getElementById('quiz-mode')?.addEventListener('change',ev=>{quizMode=ev.target.value;});
 document.getElementById('start-date')?.addEventListener('change',ev=>{if(ev.target.value){state.startDate=ev.target.value;save();render({keepScroll:true});toast('学习计划日期已更新');}});
 document.getElementById('import-file')?.addEventListener('change',async ev=>{const file=ev.target.files?.[0];if(!file)return;if(file.size>2e6){toast('备份文件过大，请选择小于 2 MB 的 JSON。');return;}try{const imported=normalizeState(JSON.parse(await file.text()),catalog);if(!confirm('导入将替换本机的学习记录。建议先导出当前备份。继续吗？'))return;state=imported;save();quiz=null;render();toast('学习备份已导入');}catch(err){toast(err.message||'文件读取失败');}});
}
function startQuiz(mode=quizMode,conceptId=null){
 let pool,label;
 if(conceptId){pool=questions.filter(q=>q.conceptId===conceptId);label='概念理解检查';}
 else if(mode==='review'){pool=questions.filter(q=>state.answers[q.id]&&!state.answers[q.id].correct);label='错题复习';}
 else if(mode.startsWith('week-')){const w=Number(mode.slice(5));pool=questions.filter(q=>q.week===w);label=`第 ${w} 周理解检查`;}
 else if(mode.startsWith('stage-')){const n=Number(mode.slice(6));pool=questions.filter(q=>q.week<=n);label=`阶段综合 · 第 1–${n} 周`;}
 else{pool=[...questions];label='全景诊断';}
 if(!pool.length){toast('这个范围暂无待复习题目。可以选择全景诊断。');return;}
 // Rotate each week's questions by past attempts before sampling across weeks.
 const byWeek=new Map();for(const q of pool){if(!byWeek.has(q.week))byWeek.set(q.week,[]);byWeek.get(q.week).push(q);}
 for(const arr of byWeek.values())arr.sort((a,b)=>(state.answers[a.id]?.attempts||0)-(state.answers[b.id]?.attempts||0));
 if(!conceptId&&(mode==='diagnostic'||mode.startsWith('stage-'))){const ordered=[];let round=0;while(ordered.length<pool.length){for(const arr of byWeek.values())if(arr[round])ordered.push(arr[round]);round++;}pool=mode==='diagnostic'?ordered.filter((_,i)=>i%2===0).slice(0,8):ordered.slice(0,12);}
 quiz={pool,index:0,correct:0,responses:[],finished:false,label};selectedAnswer=null;
 if(route().page!=='assessment'){location.hash='#/assessment';}else render({keepScroll:true});
}
function submitQuiz(){if(!quiz||selectedAnswer===null||quiz.responses[quiz.index])return;const q=quiz.pool[quiz.index],correct=selectedAnswer===q.answer;quiz.responses.push({question:q,correct,selected:selectedAnswer});if(correct)quiz.correct++;state.answers[q.id]={selected:selectedAnswer,correct,at:new Date().toISOString(),attempts:(state.answers[q.id]?.attempts||0)+1};save();render({keepScroll:true});}
function nextQuiz(){if(!quiz?.responses[quiz.index])return;if(quiz.index+1===quiz.pool.length){quiz.finished=true;state.examHistory.push({at:new Date().toISOString(),label:quiz.label,correct:quiz.correct,total:quiz.pool.length});state.examHistory=state.examHistory.slice(-60);save();}else{quiz.index++;selectedAnswer=null;}render({keepScroll:true});}

function updateCodeResult(id){const el=document.getElementById('code-result');if(el&&document.getElementById('code-editor')?.dataset.exercise===id)el.innerHTML=renderCodeResult(id);}
function stopRunner(show=true){clearTimeout(runnerTimeout);runner?.terminate();runner=null;runnerBusy=false;document.getElementById('run-code')?.classList.remove('hidden');document.getElementById('stop-code')?.classList.add('hidden');if(show){const id=document.getElementById('code-editor')?.dataset.exercise;if(id){runResults[id]={error:'执行已停止。可以修改代码后重新运行。',tests:[]};updateCodeResult(id);}}}
function runCode(id){if(runnerBusy)return;const ex=exercises.find(x=>x.id===id),editor=document.getElementById('code-editor');if(!ex||!editor)return;state.code[id]=editor.value;save();runnerBusy=true;runResults[id]={loading:true,message:'准备 Python 环境…首次加载需要联网。'};updateCodeResult(id);document.getElementById('run-code').classList.add('hidden');document.getElementById('stop-code').classList.remove('hidden');runner=new Worker('./python-worker.js');
 const fail=message=>{runResults[id]={error:message,tests:[]};stopRunner(false);updateCodeResult(id);};
 runnerTimeout=setTimeout(()=>fail('Python 运行时加载超时。请检查网络后重试，也可以下载练习在本地运行。'),120000);
 runner.onerror=err=>fail('Python 运行环境启动失败：'+err.message+'。可下载代码在本地运行。');
 runner.onmessage=({data})=>{if(data.type==='status'){runResults[id]={loading:true,message:data.message};updateCodeResult(id);}else if(data.type==='ready'){clearTimeout(runnerTimeout);runnerTimeout=setTimeout(()=>fail('代码执行超过 15 秒，已停止。检查是否存在无限循环或过大的计算。'),15000);runResults[id]={loading:true,message:'Python 已就绪，正在执行代码与断言…'};updateCodeResult(id);}else if(data.type==='error'){fail(data.message);}else if(data.type==='result'){runResults[id]=data.result;const r=data.result;state.codeResults[id]={passed:r.tests.filter(t=>t.passed).length,total:ex.tests.length,at:new Date().toISOString(),usedSolution:state.solutionsViewed.includes(id)};save();stopRunner(false);updateCodeResult(id);}};
 runner.postMessage({code:editor.value,tests:ex.tests});
}

function openExperiment(prefill={}){
 const x={title:'',hypothesis:'',baseline:'',variable:'',dataset:'',seed:'42',budget:'',metric:'',result:'',interpretation:'',next:'',status:'draft',...prefill};
 const fields=[['title','实验名称','例如：输入噪声对连续预测的影响',true],['hypothesis','要验证的假设','预期会改变什么？为什么？',true],['baseline','基线与版本','模型、配置与代码版本'],['variable','本次改变的变量','一次先改变一个主要因素'],['dataset','数据与划分','数据版本；训练 / 验证划分'],['seed','随机种子','42'],['budget','训练预算','步数、样本量、设备与时间'],['metric','评测方式','单步与多步误差、成功率等'],['result','实际结果','记录数值、失败样例和证据来源',true],['interpretation','如何解释','哪些证据支持结论？还有其他解释吗？',true],['next','下一步实验','根据证据，下一次验证什么？',true]];
 const overlay=document.createElement('div');overlay.className='modal-overlay';overlay.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-labelledby="experiment-title"><div class="between"><h2 id="experiment-title">${x.id?'编辑实验记录':'创建实验记录'}</h2><button class="modal-close" data-action="close-modal" aria-label="关闭">${icon('close')}</button></div><p>先把问题说清楚，再用实验回答。只保存在当前浏览器。</p><form id="experiment-form"><div class="form-grid">${fields.map(([key,label,placeholder,full])=>`<label class="form-field ${full?'full':''}">${label}${['hypothesis','result','interpretation','next'].includes(key)?`<textarea name="${key}" placeholder="${placeholder}" maxlength="8000">${e(x[key])}</textarea>`:`<input type="text" name="${key}" value="${e(x[key])}" placeholder="${placeholder}" ${key==='title'?'required maxlength="160"':'maxlength="2000"'}>`}</label>`).join('')}<label class="form-field">实验状态<select name="status">${[['draft','计划中'],['running','进行中'],['analyzed','已分析']].map(([v,l])=>`<option value="${v}" ${x.status===v?'selected':''}>${l}</option>`).join('')}</select></label></div><div class="modal-actions"><button type="button" class="btn" data-action="close-modal">取消</button><button type="submit" class="btn btn-primary">保存实验</button></div></form></section>`;
 document.body.append(overlay);document.body.style.overflow='hidden';overlay.querySelector('input').focus();
 overlay.addEventListener('click',ev=>{if(ev.target===overlay)closeModal();});overlay.addEventListener('keydown',ev=>{if(ev.key==='Escape')closeModal();if(ev.key==='Tab'){const els=[...overlay.querySelectorAll('button,input,textarea,select')].filter(el=>!el.disabled);const first=els[0],last=els.at(-1);if(ev.shiftKey&&document.activeElement===first){ev.preventDefault();last.focus();}else if(!ev.shiftKey&&document.activeElement===last){ev.preventDefault();first.focus();}}});
 overlay.querySelector('form').addEventListener('submit',ev=>{ev.preventDefault();const data=Object.fromEntries(new FormData(ev.target));if(!data.title.trim()){toast('请填写实验名称');return;}const now=new Date().toISOString();const exp={...data,id:x.id||crypto.randomUUID(),createdAt:x.createdAt||now,updatedAt:now};const i=state.experiments.findIndex(t=>t.id===x.id);if(i>=0)state.experiments[i]=exp;else state.experiments.unshift(exp);save();closeModal();toast('实验记录已保存');if(route().page==='notebook')render({keepScroll:true});});
}
function closeModal(){document.querySelector('.modal-overlay')?.remove();document.body.style.overflow='';document.querySelector('[data-action="new-experiment"]')?.focus();}
function exportExperiment(x){const labels={hypothesis:'假设',baseline:'基线',variable:'改变的变量',dataset:'数据与划分',seed:'随机种子',budget:'训练预算',metric:'评测',result:'结果',interpretation:'解释与局限',next:'下一步'};download('model-craft-experiment.md',`# ${x.title}\n\n${Object.entries(labels).map(([k,l])=>`## ${l}\n\n${x[k]||'待填写'}\n`).join('\n')}`,'text/markdown;charset=utf-8');}

document.addEventListener('click',ev=>{const btn=ev.target.closest('[data-action]');if(!btn)return;const {action,id,week,index}=btn.dataset;
 switch(action){
 case 'skip-content':ev.preventDefault();document.getElementById('main')?.focus();break;
 case 'menu':menuOpen=!menuOpen;render({keepScroll:true});break;
 case 'search':conceptSearch='';conceptCategory='all';bookmarksOnly=false;if(route().page==='concepts'){render();document.getElementById('concept-search')?.focus();}else{location.hash='#/concepts';setTimeout(()=>document.getElementById('concept-search')?.focus(),50);}break;
 case 'complete-lesson':state.completedLessons=state.completedLessons.includes(id)?state.completedLessons.filter(x=>x!==id):[...state.completedLessons,id];save();render({keepScroll:true});toast(state.completedLessons.includes(id)?'阅读已记录。再通过测验与代码检验理解。':'已撤销阅读标记');break;
 case 'category':conceptCategory=id;render({keepScroll:true});break;
 case 'bookmarks':bookmarksOnly=!bookmarksOnly;render({keepScroll:true});break;
 case 'clear-search':conceptSearch='';conceptCategory='all';bookmarksOnly=false;render();break;
 case 'bookmark':state.bookmarks=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];save();render({keepScroll:true});break;
 case 'week-quiz':quizMode='week-'+week;startQuiz();break;
 case 'concept-quiz':startQuiz('concept',id);break;
 case 'start-quiz':startQuiz();break;
 case 'quiz-option':if(!quiz?.responses[quiz.index]){selectedAnswer=Number(index);render({keepScroll:true});}break;
 case 'quiz-submit':submitQuiz();break;
 case 'quiz-next':nextQuiz();break;
 case 'run-code':runCode(id);break;
 case 'stop-code':stopRunner();break;
 case 'code-hint':{const ex=exercises.find(x=>x.id===id);hintCounts[id]=Math.min(ex.hints.length,(hintCounts[id]||0)+1);document.getElementById('code-hints').innerHTML=renderHints(ex);break;}
 case 'code-solution':{if(!confirm('建议先独立尝试。查看参考解法后，该练习会记录“看过参考解法”。继续吗？'))break;const ex=exercises.find(x=>x.id===id);state.code[id]=ex.solution;if(!state.solutionsViewed.includes(id))state.solutionsViewed.push(id);save();document.getElementById('code-editor').value=ex.solution;toast('参考解法已载入。请逐行解释后再运行。');break;}
 case 'code-reset':{if(!confirm('重置会替换当前练习代码，继续吗？'))break;const ex=exercises.find(x=>x.id===id);state.code[id]=ex.starter;save();document.getElementById('code-editor').value=ex.starter;break;}
 case 'download-code':download(`${id}.py`,document.getElementById('code-editor').value,'text/x-python');break;
 case 'new-experiment':openExperiment();break;
 case 'edit-experiment':openExperiment(state.experiments.find(x=>x.id===id));break;
 case 'delete-experiment':if(confirm('删除这份实验记录？此操作只影响当前浏览器。')){state.experiments=state.experiments.filter(x=>x.id!==id);save();render({keepScroll:true});toast('实验记录已删除');}break;
 case 'export-experiment':exportExperiment(state.experiments.find(x=>x.id===id));break;
 case 'close-modal':closeModal();break;
 case 'experiment-template':openExperiment({title:'视觉 AR 输入噪声与连续预测',hypothesis:'适量输入噪声可能改善自由运行时对预测误差的鲁棒性；过大噪声可能损害单步精度。',baseline:'记录代码版本、模型初始化和一份明确可复现的配置。',variable:'输入噪声策略 / 幅度',dataset:'固定训练集与按轨迹划分的独立验证集',budget:'固定有效训练样本量与更新次数；对关键结果做重复验证',metric:'teacher-forcing 单步误差；free-running 不同 horizon 的误差；动作条件一致性',status:'draft'});break;
 case 'export-progress':download(`model-craft-progress-${localDate()}.json`,JSON.stringify(state,null,2));toast('备份已导出');break;
 case 'import-progress':document.getElementById('import-file').click();break;
 case 'reset-progress':if(confirm('将清空本机的阅读、答题、代码、笔记和实验记录。请先导出备份。确定清空？')){stopRunner(false);state=createState();quiz=null;runResults={};save();render();toast('已清空本机学习记录');}break;
 }
});
document.addEventListener('keydown',ev=>{if((ev.metaKey||ev.ctrlKey)&&ev.key.toLowerCase()==='k'){ev.preventDefault();document.querySelector('[data-action="search"]')?.click();}});
window.addEventListener('hashchange',()=>{menuOpen=false;closeModal();if(runnerBusy)stopRunner(false);render();});
window.addEventListener('storage',ev=>{if(ev.key===STORAGE_KEY&&ev.newValue){try{state=normalizeState(JSON.parse(ev.newValue),catalog);toast('已同步同一浏览器中另一页面的进度');}catch{}}});
render();
